           // Last error code seen on the RQ.","    bool monitored_by;  // Whether the QP is monitored by a service.","};","","/**"," * @brief GPUNetIO QP Error info."," */","struct doca_gpu_verbs_qp_error_info {","    bool has_error;","    int syndrome;","    int vendor_err_synd;","    int hw_err_synd;","    int hw_synd_type;","    int wqe_counter;","};","","/**"," * @brief Create a DOCA GPUNETIO handler."," *"," * @param [in] gpu_bus_id"," * GPU PCIe address."," * @param [out] gpu_dev"," * Pointer to the newly created gpu device handler."," *"," * @return"," * DOCA_SUCCESS - in case of success."," * doca_error code - in case of failure:"," * - DOCA_ERROR_INVALID_VALUE - gpu_dev argument is a NULL pointer."," * - DOCA_ERROR_NOT_FOUND - GPU not found at the input PCIe address"," * - DOCA_ERROR_NO_MEMORY - failed to alloc doca_gpu."," *"," */","doca_error_t doca_gpu_create(const char *gpu_bus_id, doca_gpu_t **gpu_dev);","","/**"," * @brief Destroy a DOCA GPUNETIO handler."," *"," * @param [in] gpu_dev"," * Pointer to handler to be destroyed."," *"," * @return"," * DOCA_SUCCESS - in case of success."," * doca_error code - in case of failure:"," */","doca_error_t doca_gpu_destroy(doca_gpu_t *gpu_dev);","","/**"," * Allocate a GPU accessible memory buffer. Assumes DPDK has been already attached with"," * doca_gpu_to_dpdk(). According to the memory type specified, the buffer can be allocated in:"," * - DOCA_GPU_MEM_TYPE_GPU memptr_gpu is not NULL while memptr_cpu is NULL."," * - DOCA_GPU_MEM_TYPE_GPU_CPU both memptr_gpu and memptr_cpu are not NULL."," * - DOCA_GPU_MEM_TYPE_CPU_GPU both memptr_gpu and memptr_cpu are not NULL."," * - DOCA_GPU_MEM_TYPE_GPU_CPU_DATA_DIRECT both memptr_gpu and memptr_cpu are not NULL."," *"," * @param [in] gpu_dev"," * DOCA GPUNetIO handler."," * @param [in] size"," * Buffer size in bytes."," * @param [in] alignment"," * Buffer memory alignment."," * If 0, the return is a pointer that is suitably aligned"," * for any kind of variable (in the same manner as malloc())."," * Otherwise, the return is a pointer that is a multiple of *align*."," * Alignment value must be a power of two."," * @param [in] mtype"," * Type of memory buffer. See enum doca_gpu_memtype for reference."," * @param [out] memptr_gpu"," * GPU memory pointer. Must be used with CUDA API and within CUDA kernels."," * @param [out] memptr_cpu"," * CPU memory pointer. Must be used for CPU direct access to the memory."," *"," * @return"," * Non NULL memptr_gpu pointer on success, NULL otherwise."," * Non NULL memptr_cpu pointer on success in case of DOCA_GPU_MEM_TYPE_CPU_GPU and"," * DOCA_GPU_MEM_TYPE_GPU_CPU and DOCA_GPU_MEM_TYPE_GPU_CPU_DATA_DIRECT, NULL otherwise."," * DOCA_SUCCESS - in case of success. doca_error code - in case of failure:"," * - DOCA_ERROR_INVALID_VALUE - if an invalid input had been received."," * - DOCA_ERROR_NO_MEMORY - if an error occurred dealing with GPU memory."," */","doca_error_t doca_gpu_mem_alloc(doca_gpu_t *gpu_dev, size_t size, size_t alignment,","                                enum doca_gpu_mem_type mtype, void **memptr_gpu, void **memptr_cpu);","","/**"," * Free a GPU memory buffer."," * Only memory allocated with doca_gpu_mem_alloc() can be freed with this function."," *"," * @param [in] gpu"," * DOCA GPUNetIO handler."," * @param [in] memptr_gpu"," * GPU memory pointer to be freed."," *"," * @return"," * DOCA_SUCCESS - in case of success."," * doca_error code - in case of failure:"," * - DOCA_ERROR_INVALID_VALUE - if an invalid input had been received."," */","doca_error_t doca_gpu_mem_free(doca_gpu_t *gpu, void *memptr_gpu);","","/**"," * Create a GPU handler for a Verbs QP object"," *"," * @param [in] gpu_dev"," * DOCA GPUNetIO handler."," * @param [in] qp"," * DOCA network device handler."," * @param [in] nic_handler"," * Type of NIC handler for this QP."," * @param [in] gpu_qp_umem_dev_ptr"," * GPU external UMEM."," * @param [in] cq_sq"," * DOCA Verbs CQ SQ CPU object connected to the QP."," * @param [in] cq_rq"," * DOCA Verbs CQ RQ CPU object connected to the QP, or NULL when the QP has no RQ."," * @param [in] dbr_cpu_ptr"," * CPU-accessible QP DBR address required when cq_rq is not NULL."," * @param [in] send_dbr_mode_ext"," * Send DBR mode."," * @param [in] cq_type"," * CQ type."," * @param [in] enable_data_direct"," * Whether to enable data direct support for this QP."," * @param [out] qp_out"," * DOCA GPUNetIO Verbs QP object."," *"," * @return"," * DOCA_SUCCESS - in case of success."," * doca_error code - in case of failure:"," * - DOCA_ERROR_INVALID_VALUE - if an invalid input had been received."," */","doca_error_t doca_gpu_verbs_export_qp(doca_gpu_t *gpu_dev, struct doca_verbs_qp_t *qp,","                                      enum doca_gpu_dev_verbs_nic_handler nic_handler,","                                      void *gpu_qp_umem_dev_ptr, struct doca_verbs_cq_t *cq_sq,","                                      struct doca_verbs_cq_t *cq_rq, void *dbr_cpu_ptr,","                                      enum doca_gpu_verbs_send_dbr_mode_ext send_dbr_mode_ext,","                                      enum doca_gpu_dev_verbs_cq_type cq_type,","                                      bool enable_data_direct, struct doca_gpu_verbs_qp **qp_out);","","/**"," * Destroy a GPU handler for a Verbs QP object"," *"," * @param [in] gpu_dev"," * DOCA GPUNetIO handler."," * @param [in] qp_cpu"," * DOCA Verbs QP CPU object."," *"," * @return"," * DOCA_SUCCESS - in case of success."," * doca_error code - in case of failure:"," * - DOCA_ERROR_INVALID_VALUE - if an invalid input had been received."," */","doca_error_t doca_gpu_verbs_unexport_qp(doca_gpu_t *gpu_dev, struct doca_gpu_verbs_qp *qp);","","/**"," * Get a GPUNetIO GPU device handler handler from a GPUNetIO Verbs QP object."," *"," * @param [in] qp"," * DOCA GPUNetIO Verbs QP object."," * @param [out] qp_gpu"," * DOCA GPUNetIO Verbs QP GPU object."," *"," * @return"," * DOCA_SUCCESS - in case of success."," * doca_error code - in case of failure:"," * - DOCA_ERROR_INVALID_VALUE - if an invalid input had been received."," */","doca_error_t doca_gpu_verbs_get_qp_dev(struct doca_gpu_verbs_qp *qp,","                                       struct doca_gpu_dev_verbs_qp **qp_gpu);","","/**"," * Return a DMABuf file descriptor from a GPU memory address if the GPU device and CUDA installation"," * supports DMABuf."," *"," * @param [in] gpu_dev"," * DOCA GPUNetIO handler."," * @param [in] memptr_gpu"," * GPU memory pointer to be freed."," * @param [in] size"," * Size in bytes to map."," * @param [out] dmabuf_fd"," * DMABuf file descriptor"," *"," * @return"," * DOCA_SUCCESS - in case of success."," * doca_error code - in case of failure:"," * - DOCA_ERROR_INVALID_VALUE - if an invalid input had been received."," * - DOCA_ERROR_NOT_SUPPORTED - DMABuf not supported"," */","doca_error_t doca_gpu_get_dmabuf_fd(doca_gpu_t *gpu_dev, void *memptr_gpu, size_t size,","                                    int *dmabuf_fd);","","/**"," * Check if UAR can be registered on GPU"," *"," * @param [in] db"," * UAR address"," * @param [out] out_can_register"," * Can register on GPU"," *"," * @return"," * DOCA_SUCCESS - in case of success."," * doca_error code - in case of failure:"," * - DOCA_ERROR_INVALID_VALUE - if an invalid input had been received."," */","doca_error_t doca_gpu_verbs_can_gpu_register_uar(void *db, bool *out_can_register);","","/**"," * Export UAR to GPU"," *"," * @param [in] sq_db"," * SQ UAR address"," * @param [out] uar_addr_gpu"," * SQ UAR GPU address"," *"," * @return"," * DOCA_SUCCESS - in case of success."," * doca_error code - in case of failure:"," * - DOCA_ERROR_INVALID_VALUE - if an invalid input had been received."," * - DOCA_ERROR_DRIVER - if UAR mapping failed"," */","doca_error_t doca_gpu_verbs_export_uar(uint64_t *sq_db, uint64_t **uar_addr_gpu);","","/**"," * Unexport UAR from GPU"," *"," * @param [in] uar_addr_gpu"," * SQ UAR GPU address"," *"," * @return"," * DOCA_SUCCESS - 